   "ble_spam_apple": {
    "v": "yes",
    "note": "Apple Continuity. Real, but oversold. The STM32WB55 BLE stack advertises one payload at a time and cycles through them, so this is protocol-level nuisance advertising, not RF jamming and not a flood. Apple (iOS 17.2+), Google, Microsoft and Samsung all added cooldowns and sanity checks after 2023, so on current phones it is mostly a party trick. The app's own author describes it that way."
   },
   "ble_spam_android": {
    "v": "yes",
    "note": "Google Fast Pair. Real, but oversold. The STM32WB55 BLE stack advertises one payload at a time and cycles through them, so this is protocol-level nuisance advertising, not RF jamming and not a flood. Apple (iOS 17.2+), Google, Microsoft and Samsung all added cooldowns and sanity checks after 2023, so on current phones it is mostly a party trick. The app's own author describes it that way."
   },
   "ble_spam_samsung": {
    "v": "yes",
    "note": "Samsung EasySetup. Real, but oversold. The STM32WB55 BLE stack advertises one payload at a time and cycles through them, so this is protocol-level nuisance advertising, not RF jamming and not a flood. Apple (iOS 17.2+), Google, Microsoft and Samsung all added cooldowns and sanity checks after 2023, so on current phones it is mostly a party trick. The app's own author describes it that way."
   },
   "ble_spam_swift_pair": {
    "v": "yes",
    "note": "Microsoft Swift Pair. Real, but oversold. The STM32WB55 BLE stack advertises one payload at a time and cycles through them, so this is protocol-level nuisance advertising, not RF jamming and not a flood. Apple (iOS 17.2+), Google, Microsoft and Samsung all added cooldowns and sanity checks after 2023, so on current phones it is mostly a party trick. The app's own author describes it that way."
   },
   "findmy_track": {
    "v": "yes",
    "note": "Read this carefully because the name misleads everyone: FindMy Flipper does NOT find or track other people's AirTags. It turns the Flipper itself INTO a trackable tag, broadcasting a BLE beacon that Apple's Find My network (or Samsung SmartThings / Tile) picks up, so YOU can locate your own Flipper. Setup is either cloning an existing tag's MAC and payload (which requires killing the original tag's battery so it stops rotating keys) or generating OpenHaystack key pairs with Docker/Python on a PC and importing a .keys file. It is an app, not a radio feature - the underlying hardware capability is just 'BLE can advertise'."
   },
   "ble_tracker_detect": {
    "v": "partial",
    "note": "Separate community apps scan for tracker advertisements and match on service UUID / manufacturer data. Not the same thing as FindMy Flipper, and not a firmware feature."
   }
